using System.ComponentModel;

namespace Runic.Translations.Generated;

/// <summary>Version numbers shared by generated code and the runtime.</summary>
/// <remarks>
/// Generated-code support: binary compatible for code that an earlier release of the same major generated; not intended
/// for hand-written code. The version rule: code generated by release N runs on runtime N or later within the same major.
/// A runtime therefore supports every ABI from its <c>Minimum*</c> constant up to its current one, and generated code
/// checks its requirement with a call (<see cref="EnsureRuntimeAbi"/>, <see cref="EnsureRmf2RuntimeAbi"/>), which runs
/// against the runtime that is loaded, not the one it was compiled against.
/// </remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public static class TranslationsCompatibility
{
    /// <summary>The ABI version embedded into generated C#.</summary>
    public const int RuntimeAbiVersion = 1;

    /// <summary>The oldest base ABI this runtime still runs.</summary>
    public const int MinimumRuntimeAbiVersion = 1;

    /// <summary>The ABI for v5 typed expression evaluation and RMF2 markup contract v2.</summary>
    public const int Rmf2RuntimeAbiVersion = 3;

    /// <summary>The oldest RMF2 ABI this runtime still runs; earlier ones predate the RMF2 v5 carrier.</summary>
    public const int MinimumRmf2RuntimeAbiVersion = 3;

    /// <summary>
    /// The additive typed slot binding surface (<see cref="IRmf2SlotBindings{TSelf}"/>, <see cref="LocalizedTextContent{TSlots}"/>).
    /// The source generator emits the readable C# surface only when the referenced runtime declares this constant.
    /// The value only grows additively: a newer runtime keeps supporting v1-shaped generated code.
    /// </summary>
    public const int TypedSlotBindingsVersion = 1;

    /// <summary>
    /// The additive catalog composition surface (<see cref="ITranslationContext"/>, <see cref="TranslationCatalogRegistration"/>).
    /// The source generator emits <c>XCatalog.Registration</c> and the <c>XText(ITranslationContext)</c> constructor only when
    /// the referenced runtime declares this constant. The value only grows additively.
    /// </summary>
    public const int CompositionVersion = 1;

    /// <summary>Checks a generated base ABI requirement against the executing runtime, without const inlining.</summary>
    public static bool SupportsRuntimeAbi(int requiredVersion) =>
        requiredVersion >= MinimumRuntimeAbiVersion && requiredVersion <= RuntimeAbiVersion;

    /// <summary>Rejects code generated for a base ABI that the executing runtime does not run (RTR0024).</summary>
    public static void EnsureRuntimeAbi(int requiredVersion)
    {
        if (!SupportsRuntimeAbi(requiredVersion))
            throw new System.InvalidOperationException("RTR0024: Generated translation code is incompatible with the referenced runtime ABI.");
    }

    /// <summary>Checks an embedded RMF2 ABI requirement against the executing runtime, without const inlining.</summary>
    /// <remarks>Code generated for an earlier RMF2 ABI of the same major keeps running on a later runtime.</remarks>
    public static bool SupportsRmf2RuntimeAbi(int requiredVersion) =>
        requiredVersion >= MinimumRmf2RuntimeAbiVersion && requiredVersion <= Rmf2RuntimeAbiVersion;

    /// <summary>Rejects an unsupported generated RMF2 ABI requirement before message construction.</summary>
    public static void EnsureRmf2RuntimeAbi(int requiredVersion)
    {
        if (!SupportsRmf2RuntimeAbi(requiredVersion))
            throw new System.NotSupportedException("The generated RMF2 message requires an unsupported runtime ABI.");
    }
}
